-- v8: English daily pack. One row per calendar day, generated by the Claude API on demand:
-- phrases for day-to-day articulation, a 2 to 3 minute speaking topic for bedtime, and a
-- 5 minute read-aloud passage. The Kindle shows it; the dashboard steers themes and focus.
CREATE TABLE IF NOT EXISTS english_packs (
  day          DATE PRIMARY KEY,
  pack         JSONB NOT NULL DEFAULT '{}',   -- phrases, topic, passage (see internal/english)
  model        TEXT NOT NULL DEFAULT '',
  status       TEXT NOT NULL DEFAULT 'ready',  -- ready | error
  error        TEXT NOT NULL DEFAULT '',
  generated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  read_done    BOOLEAN NOT NULL DEFAULT false, -- read the passage aloud
  spoke_done   BOOLEAN NOT NULL DEFAULT false, -- spoke on the topic
  note         TEXT NOT NULL DEFAULT ''        -- your own note after practising
);
-- kv keys added: english_prefs (themes, focus, phrase_count, passage_words)
